<div class="row justify-content-center"><div class="col-lg-8"><a href="/events/<?= (int)$event['id'] ?>" class="small text-decoration-none">← Back to event</a><section class="lh-card mt-3"><h1 class="h3">Edit event</h1><form method="post" action="/events/<?= (int)$event['id'] ?>/edit" class="d-grid gap-3"><input type="hidden" name="_token" value="<?=e($_SESSION['csrf'])?>"><input class="form-control" name="title" value="<?=e($event['title'])?>" required><input class="form-control" type="date" name="event_date" value="<?=e($event['event_date'])?>" required><input class="form-control" name="location" value="<?=e($event['location'])?>" required><div class="row g-2"><div class="col"><input class="form-control" type="time" name="start_time" value="<?=e(substr((string)$event['start_time'],0,5))?>"></div><div class="col"><input class="form-control" type="time" name="end_time" value="<?=e(substr((string)$event['end_time'],0,5))?>"></div></div><select class="form-select" name="organizer" data-organizer-select><?php foreach($organizers as$o):?><option value="<?=e($o['name'])?>" <?=$event['organizer_id']==$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?><option value="__other__">Others</option></select><input class="form-control d-none" name="custom_organizer" data-custom-organizer placeholder="Organizer name"><input class="form-control" type="url" name="website_url" value="<?=e($event['website_url'])?>"><textarea class="form-control" name="description" rows="5" required><?=e($event['description'])?></textarea><textarea class="form-control" name="material_request" rows="2"><?=e($event['material_request'])?></textarea><button class="btn btn-lh-primary">Save changes</button></form></section></div></div><script>document.querySelector('[data-organizer-select]').addEventListener('change',function(){let i=this.form.querySelector('[data-custom-organizer]');i.classList.toggle('d-none',this.value!=='__other__');i.required=this.value==='__other__';});</script>
